package report

import "billing-api/internal/api"

// def is one report: columns and the SQL that produces them. The SQL uses
// named arguments @from, @to (dates), @location (smallint), @category (int),
// @party (bigint); unused ones are ignored. Column keys must match the SQL
// aliases. Sum marks columns totalled in the footer.
//
// Reports are dynamic tables (columns differ per key), so they are the one
// place SQL is not generated by sqlc; every key is exercised by the server
// integration tests.
type def struct {
	Title   string
	Columns []api.ReportColumn
	Sum     []string
	SQL     string
}

func col(key, label, typ string) api.ReportColumn {
	return api.ReportColumn{Key: key, Label: label, Type: typ}
}

// sales bills: active, posting to the ledger (Account copies excluded, BR-04).
const salesBills = `b.status = 'active' AND b.posts_to_ledger AND b.bill_date BETWEEN @from AND @to
  AND (@party::bigint IS NULL OR b.party_id = @party)
  AND (@location::smallint IS NULL OR EXISTS (SELECT 1 FROM bill_line x WHERE x.bill_id = b.id AND x.location_id = @location))`

var defs = map[string]def{
	"sales-register": {
		Title: "Sales register",
		Columns: []api.ReportColumn{col("bill_date", "Date", "date"), col("bill_no", "Bill no", "text"), col("bill_type", "Type", "text"),
			col("customer", "Customer", "text"), col("gstin", "GSTIN", "text"), col("taxable", "Taxable", "money"),
			col("cgst", "CGST", "money"), col("sgst", "SGST", "money"), col("igst", "IGST", "money"),
			col("total", "Total", "money"), col("paid", "Paid", "money"), col("balance", "Balance", "money"),
			col("payment_status", "Payment", "text")},
		Sum: []string{"taxable", "cgst", "sgst", "igst", "total", "paid", "balance"},
		SQL: `SELECT b.bill_date, b.bill_no, b.bill_type::text AS bill_type, b.cust_name AS customer, coalesce(b.cust_gstin, '') AS gstin,
       b.taxable_total AS taxable, b.cgst, b.sgst, b.igst, b.grand_total AS total, b.amount_paid AS paid, b.balance_due AS balance,
       CASE WHEN b.balance_due <= 0 THEN 'paid' WHEN b.amount_paid > 0 THEN 'partial' ELSE 'unpaid' END AS payment_status
FROM bill b WHERE ` + salesBills + ` ORDER BY b.bill_date, b.bill_no`,
	},
	"bill-type-register": {
		Title: "Bill-type register",
		Columns: []api.ReportColumn{col("bill_date", "Date", "date"), col("bill_no", "Bill no", "text"), col("bill_type", "Type", "text"),
			col("status", "Status", "text"), col("customer", "Customer", "text"), col("total", "Total", "money"),
			col("source_bill_no", "Copied from", "text"), col("account_copy_no", "Account copy", "text")},
		Sum: []string{"total"},
		SQL: `SELECT b.bill_date, b.bill_no, b.bill_type::text AS bill_type, b.status::text AS status, b.cust_name AS customer,
       b.grand_total AS total, coalesce(s.bill_no, '') AS source_bill_no, coalesce(c.bill_no, '') AS account_copy_no
FROM bill b
LEFT JOIN bill s ON s.id = b.source_bill_id
LEFT JOIN LATERAL (SELECT bill_no FROM bill c WHERE c.source_bill_id = b.id AND c.status <> 'cancelled' LIMIT 1) c ON true
WHERE b.status <> 'draft' AND b.bill_date BETWEEN @from AND @to AND (@party::bigint IS NULL OR b.party_id = @party)
ORDER BY b.bill_date, b.bill_type, b.bill_no`,
	},
	"item-sales": {
		Title: "Item-wise sales",
		Columns: []api.ReportColumn{col("item", "Item", "text"), col("category", "Category", "text"), col("qty", "Qty", "qty"),
			col("unit", "Unit", "text"), col("sales", "Sales (taxable)", "money"), col("cost", "Cost", "money"),
			col("profit", "Profit", "money"), col("margin_pct", "Margin %", "percent")},
		Sum: []string{"sales", "cost", "profit"},
		SQL: `SELECT i.name AS item, c.name AS category, sum(bl.base_qty) AS qty, u.symbol AS unit, sum(bl.taxable_value) AS sales,
       sum(round(bl.base_qty * coalesce(bl.unit_cost, 0), 2)) AS cost,
       sum(bl.taxable_value) - sum(round(bl.base_qty * coalesce(bl.unit_cost, 0), 2)) AS profit,
       CASE WHEN sum(bl.taxable_value) > 0 THEN round((sum(bl.taxable_value) - sum(round(bl.base_qty * coalesce(bl.unit_cost, 0), 2))) * 100 / sum(bl.taxable_value), 2) ELSE 0 END AS margin_pct
FROM bill_line bl JOIN bill b ON b.id = bl.bill_id JOIN item i ON i.id = bl.item_id JOIN category c ON c.id = i.category_id
JOIN unit u ON u.id = i.base_unit_id
WHERE b.status = 'active' AND b.posts_to_ledger AND b.bill_date BETWEEN @from AND @to
  AND (@party::bigint IS NULL OR b.party_id = @party) AND (@location::smallint IS NULL OR bl.location_id = @location)
  AND (@category::int IS NULL OR i.category_id = @category)
GROUP BY i.id, i.name, c.name, u.symbol ORDER BY sales DESC, i.name`,
	},
	"category-sales": {
		Title: "Category-wise sales",
		Columns: []api.ReportColumn{col("category", "Category", "text"), col("items", "Items sold", "qty"),
			col("sales", "Sales (taxable)", "money"), col("cost", "Cost", "money"), col("profit", "Profit", "money")},
		Sum: []string{"sales", "cost", "profit"},
		SQL: `SELECT c.name AS category, count(DISTINCT bl.item_id) AS items, sum(bl.taxable_value) AS sales,
       sum(round(bl.base_qty * coalesce(bl.unit_cost, 0), 2)) AS cost,
       sum(bl.taxable_value) - sum(round(bl.base_qty * coalesce(bl.unit_cost, 0), 2)) AS profit
FROM bill_line bl JOIN bill b ON b.id = bl.bill_id JOIN item i ON i.id = bl.item_id JOIN category c ON c.id = i.category_id
WHERE b.status = 'active' AND b.posts_to_ledger AND b.bill_date BETWEEN @from AND @to
  AND (@location::smallint IS NULL OR bl.location_id = @location) AND (@category::int IS NULL OR i.category_id = @category)
GROUP BY c.id, c.name ORDER BY sales DESC`,
	},
	"gst-b2b": {
		Title: "GST B2B (GSTR-1)",
		Columns: []api.ReportColumn{col("gstin", "GSTIN", "text"), col("customer", "Customer", "text"), col("bill_no", "Invoice no", "text"),
			col("bill_date", "Date", "date"), col("invoice_value", "Invoice value", "money"), col("pos", "Place of supply", "text"),
			col("rate", "Rate %", "percent"), col("taxable", "Taxable", "money"), col("igst", "IGST", "money"),
			col("cgst", "CGST", "money"), col("sgst", "SGST", "money")},
		Sum: []string{"taxable", "igst", "cgst", "sgst"},
		SQL: `WITH t AS (
  SELECT bill_id, gst_rate, taxable_value AS taxable, igst, cgst, sgst FROM bill_line
  UNION ALL SELECT bill_id, gst_rate, amount, igst, cgst, sgst FROM bill_charge)
SELECT b.cust_gstin AS gstin, b.cust_name AS customer, b.bill_no, b.bill_date, b.grand_total AS invoice_value,
       b.place_of_supply AS pos, t.gst_rate AS rate, sum(t.taxable) AS taxable, sum(t.igst) AS igst, sum(t.cgst) AS cgst, sum(t.sgst) AS sgst
FROM bill b JOIN t ON t.bill_id = b.id
WHERE ` + salesBills + ` AND b.cust_gstin IS NOT NULL
GROUP BY b.id, t.gst_rate ORDER BY b.bill_date, b.bill_no, t.gst_rate`,
	},
	"gst-b2c": {
		Title: "GST B2C (GSTR-1)",
		Columns: []api.ReportColumn{col("pos", "Place of supply", "text"), col("rate", "Rate %", "percent"),
			col("taxable", "Taxable", "money"), col("igst", "IGST", "money"), col("cgst", "CGST", "money"), col("sgst", "SGST", "money")},
		Sum: []string{"taxable", "igst", "cgst", "sgst"},
		SQL: `WITH t AS (
  SELECT bill_id, gst_rate, taxable_value AS taxable, igst, cgst, sgst FROM bill_line
  UNION ALL SELECT bill_id, gst_rate, amount, igst, cgst, sgst FROM bill_charge)
SELECT b.place_of_supply AS pos, t.gst_rate AS rate, sum(t.taxable) AS taxable, sum(t.igst) AS igst, sum(t.cgst) AS cgst, sum(t.sgst) AS sgst
FROM bill b JOIN t ON t.bill_id = b.id
WHERE ` + salesBills + ` AND b.cust_gstin IS NULL
GROUP BY b.place_of_supply, t.gst_rate ORDER BY b.place_of_supply, t.gst_rate`,
	},
	"gst-hsn-summary": {
		Title: "HSN summary (GSTR-1)",
		Columns: []api.ReportColumn{col("hsn", "HSN/SAC", "text"), col("description", "Description", "text"), col("uqc", "UQC", "text"),
			col("qty", "Qty", "qty"), col("rate", "Rate %", "percent"), col("taxable", "Taxable", "money"), col("igst", "IGST", "money"),
			col("cgst", "CGST", "money"), col("sgst", "SGST", "money"), col("total", "Total value", "money")},
		Sum: []string{"taxable", "igst", "cgst", "sgst", "total"},
		SQL: `WITH t AS (
  SELECT bl.bill_id, bl.hsn_code AS hsn, min(bl.description) OVER (PARTITION BY bl.hsn_code) AS description,
         coalesce(u.uqc_code, 'OTH') AS uqc, bl.qty, bl.gst_rate, bl.taxable_value AS taxable, bl.igst, bl.cgst, bl.sgst
    FROM bill_line bl JOIN unit u ON u.id = bl.unit_id
  UNION ALL
  SELECT bc.bill_id, coalesce(bc.sac_code, ''), bc.description, 'OTH', 1, bc.gst_rate, bc.amount, bc.igst, bc.cgst, bc.sgst
    FROM bill_charge bc)
SELECT t.hsn, min(t.description) AS description, t.uqc, sum(t.qty) AS qty, t.gst_rate AS rate, sum(t.taxable) AS taxable,
       sum(t.igst) AS igst, sum(t.cgst) AS cgst, sum(t.sgst) AS sgst, sum(t.taxable + t.igst + t.cgst + t.sgst) AS total
FROM bill b JOIN t ON t.bill_id = b.id
WHERE ` + salesBills + `
GROUP BY t.hsn, t.uqc, t.gst_rate ORDER BY t.hsn, t.gst_rate`,
	},
	"gst-credit-notes": {
		Title: "Credit notes (GSTR-1 CDNR/CDNUR)",
		Columns: []api.ReportColumn{col("cn_no", "Credit note", "text"), col("cn_date", "Date", "date"), col("bill_no", "Against invoice", "text"),
			col("gstin", "GSTIN", "text"), col("customer", "Customer", "text"), col("taxable", "Taxable", "money"),
			col("cgst", "CGST", "money"), col("sgst", "SGST", "money"), col("igst", "IGST", "money"), col("total", "Total", "money"),
			col("einvoice", "E-invoice", "text")},
		Sum: []string{"taxable", "cgst", "sgst", "igst", "total"},
		SQL: `SELECT cn.cn_no, cn.cn_date, b.bill_no, coalesce(b.cust_gstin, '') AS gstin, b.cust_name AS customer,
       cn.taxable_total AS taxable, cn.cgst, cn.sgst, cn.igst, cn.grand_total AS total, cn.einv_status::text AS einvoice
FROM credit_note cn JOIN bill b ON b.id = cn.bill_id
WHERE cn.status = 'approved' AND cn.cn_date BETWEEN @from AND @to AND (@party::bigint IS NULL OR cn.party_id = @party)
ORDER BY cn.cn_date, cn.cn_no`,
	},
	"einvoice-status": {
		Title: "E-invoice status",
		Columns: []api.ReportColumn{col("bill_date", "Date", "date"), col("bill_no", "Bill no", "text"), col("customer", "Customer", "text"),
			col("gstin", "GSTIN", "text"), col("total", "Total", "money"), col("status", "E-invoice", "text"),
			col("irn", "IRN", "text"), col("ack_no", "Ack no", "text"), col("ewb_no", "E-way bill", "text"), col("error", "Last error", "text")},
		Sum: []string{"total"},
		SQL: `SELECT b.bill_date, b.bill_no, b.cust_name AS customer, coalesce(b.cust_gstin, '') AS gstin, b.grand_total AS total,
       b.einv_status::text AS status, coalesce(b.irn, '') AS irn, coalesce(b.ack_no, '') AS ack_no, coalesce(b.ewb_no, '') AS ewb_no,
       coalesce(b.einv_error, '') AS error
FROM bill b
WHERE b.status <> 'draft' AND b.cust_gstin IS NOT NULL AND b.bill_date BETWEEN @from AND @to
  AND (@party::bigint IS NULL OR b.party_id = @party)
ORDER BY b.bill_date, b.bill_no`,
	},
	"purchase-register": {
		Title: "Purchase register",
		Columns: []api.ReportColumn{col("received_date", "Received", "date"), col("doc_no", "GRN", "text"), col("supplier", "Dealer", "text"),
			col("supplier_invoice_no", "Dealer invoice", "text"), col("supplier_invoice_dt", "Invoice date", "date"),
			col("taxable", "Taxable", "money"), col("charges", "Freight + other", "money"), col("cgst", "CGST", "money"),
			col("sgst", "SGST", "money"), col("igst", "IGST", "money"), col("total", "Total", "money"), col("status", "Status", "text")},
		Sum: []string{"taxable", "charges", "cgst", "sgst", "igst", "total"},
		SQL: `SELECT pu.received_date, pu.doc_no, pt.name AS supplier, pu.supplier_invoice_no, pu.supplier_invoice_dt,
       pu.taxable_total AS taxable, pu.freight + pu.other_charges AS charges, pu.cgst, pu.sgst, pu.igst, pu.grand_total AS total,
       pu.status::text AS status
FROM purchase pu JOIN party pt ON pt.id = pu.supplier_id
WHERE pu.received_date BETWEEN @from AND @to AND (@party::bigint IS NULL OR pu.supplier_id = @party)
  AND (@location::smallint IS NULL OR pu.location_id = @location)
ORDER BY pu.received_date, pu.doc_no`,
	},
	"input-gst": {
		Title: "Input GST",
		Columns: []api.ReportColumn{col("supplier", "Dealer", "text"), col("gstin", "GSTIN", "text"), col("supplier_invoice_no", "Invoice", "text"),
			col("supplier_invoice_dt", "Date", "date"), col("rate", "Rate %", "percent"), col("taxable", "Taxable", "money"),
			col("igst", "IGST", "money"), col("cgst", "CGST", "money"), col("sgst", "SGST", "money")},
		Sum: []string{"taxable", "igst", "cgst", "sgst"},
		SQL: `SELECT pt.name AS supplier, coalesce(pt.gstin, '') AS gstin, pu.supplier_invoice_no, pu.supplier_invoice_dt,
       pl.gst_rate AS rate, sum(pl.taxable_value) AS taxable, sum(pl.igst) AS igst, sum(pl.cgst) AS cgst, sum(pl.sgst) AS sgst
FROM purchase pu JOIN party pt ON pt.id = pu.supplier_id JOIN purchase_line pl ON pl.purchase_id = pu.id
WHERE pu.status = 'active' AND pu.received_date BETWEEN @from AND @to AND (@party::bigint IS NULL OR pu.supplier_id = @party)
GROUP BY pu.id, pt.name, pt.gstin, pl.gst_rate ORDER BY pu.supplier_invoice_dt, pt.name`,
	},
	"stock-summary": {
		Title: "Stock summary",
		Columns: []api.ReportColumn{col("item", "Item", "text"), col("category", "Category", "text"), col("unit", "Unit", "text"),
			col("opening", "Opening", "qty"), col("qty_in", "In", "qty"), col("qty_out", "Out", "qty"), col("closing", "Closing", "qty"),
			col("avg_cost", "Avg cost", "money"), col("value", "Value", "money")},
		Sum: []string{"value"},
		SQL: `SELECT i.name AS item, c.name AS category, u.symbol AS unit,
       coalesce(sum(m.qty_in - m.qty_out) FILTER (WHERE m.created_at < @from::date), 0) AS opening,
       coalesce(sum(m.qty_in) FILTER (WHERE m.created_at >= @from::date AND m.created_at < @to::date + 1), 0) AS qty_in,
       coalesce(sum(m.qty_out) FILTER (WHERE m.created_at >= @from::date AND m.created_at < @to::date + 1), 0) AS qty_out,
       coalesce(sum(m.qty_in - m.qty_out) FILTER (WHERE m.created_at < @to::date + 1), 0) AS closing,
       round(i.avg_cost, 2) AS avg_cost,
       round(coalesce(sum(m.qty_in - m.qty_out) FILTER (WHERE m.created_at < @to::date + 1), 0) * i.avg_cost, 2) AS value
FROM item i JOIN category c ON c.id = i.category_id JOIN unit u ON u.id = i.base_unit_id
LEFT JOIN stock_movement m ON m.item_id = i.id AND (@location::smallint IS NULL OR m.location_id = @location)
WHERE i.is_active AND (@category::int IS NULL OR i.category_id = @category)
GROUP BY i.id, i.name, c.name, u.symbol ORDER BY c.name, i.name`,
	},
	"stock-movement": {
		Title: "Stock movement",
		Columns: []api.ReportColumn{col("date", "Date", "date"), col("item", "Item", "text"), col("location", "Location", "text"),
			col("kind", "Kind", "text"), col("ref_no", "Document", "text"), col("qty_in", "In", "qty"), col("qty_out", "Out", "qty"),
			col("unit_cost", "Unit cost", "money"), col("user", "User", "text")},
		Sum: []string{"qty_in", "qty_out"},
		SQL: `SELECT (m.created_at AT TIME ZONE 'Asia/Kolkata')::date AS date, i.name AS item, l.name AS location, m.kind::text AS kind,
       coalesce(fn_ref_no(m.ref_type, m.ref_id), '') AS ref_no, m.qty_in, m.qty_out, round(coalesce(m.unit_cost, 0), 2) AS unit_cost,
       coalesce(u.full_name, '') AS "user"
FROM stock_movement m JOIN item i ON i.id = m.item_id JOIN location l ON l.id = m.location_id
LEFT JOIN app_user u ON u.id = m.created_by
WHERE m.created_at >= @from::date AND m.created_at < @to::date + 1
  AND (@location::smallint IS NULL OR m.location_id = @location) AND (@category::int IS NULL OR i.category_id = @category)
ORDER BY m.id`,
	},
	"transfers": {
		Title: "Stock transfers",
		Columns: []api.ReportColumn{col("transfer_date", "Date", "date"), col("doc_no", "Transfer no", "text"), col("from_location", "From", "text"),
			col("to_location", "To", "text"), col("item", "Item", "text"), col("qty", "Qty", "qty"), col("unit", "Unit", "text"),
			col("vehicle_no", "Vehicle", "text"), col("user", "User", "text")},
		Sum: []string{},
		SQL: `SELECT t.transfer_date, t.doc_no, lf.name AS from_location, lt.name AS to_location, i.name AS item, tl.base_qty AS qty,
       u.symbol AS unit, coalesce(t.vehicle_no, '') AS vehicle_no, coalesce(au.full_name, '') AS "user"
FROM stock_transfer t JOIN stock_transfer_line tl ON tl.transfer_id = t.id JOIN item i ON i.id = tl.item_id
JOIN unit u ON u.id = i.base_unit_id JOIN location lf ON lf.id = t.from_location_id JOIN location lt ON lt.id = t.to_location_id
LEFT JOIN app_user au ON au.id = t.created_by
WHERE t.transfer_date BETWEEN @from AND @to
  AND (@location::smallint IS NULL OR t.from_location_id = @location OR t.to_location_id = @location)
  AND (@category::int IS NULL OR i.category_id = @category)
ORDER BY t.transfer_date, t.doc_no`,
	},
	"adjustments": {
		Title: "Stock adjustments",
		Columns: []api.ReportColumn{col("adj_date", "Date", "date"), col("doc_no", "Adjustment no", "text"), col("location", "Location", "text"),
			col("reason", "Reason", "text"), col("item", "Item", "text"), col("qty_change", "Qty change", "qty"),
			col("notes", "Notes", "text"), col("user", "User", "text")},
		Sum: []string{},
		SQL: `SELECT a.adj_date, a.doc_no, l.name AS location, a.reason::text AS reason, i.name AS item, al.qty_change,
       coalesce(a.notes, '') AS notes, coalesce(u.full_name, '') AS "user"
FROM stock_adjustment a JOIN stock_adjustment_line al ON al.adjustment_id = a.id JOIN item i ON i.id = al.item_id
JOIN location l ON l.id = a.location_id LEFT JOIN app_user u ON u.id = a.created_by
WHERE a.adj_date BETWEEN @from AND @to AND (@location::smallint IS NULL OR a.location_id = @location)
  AND (@category::int IS NULL OR i.category_id = @category)
ORDER BY a.adj_date, a.doc_no`,
	},
	"receivables-ageing": {
		Title: "Receivables ageing",
		Columns: []api.ReportColumn{col("party", "Customer", "text"), col("mobile", "Mobile", "text"), col("balance", "Balance", "money"),
			col("d0_30", "0-30 days", "money"), col("d31_60", "31-60 days", "money"), col("d61_90", "61-90 days", "money"),
			col("d90_plus", "90+ days", "money"), col("other", "Opening / on account", "money")},
		Sum: []string{"balance", "d0_30", "d31_60", "d61_90", "d90_plus", "other"},
		SQL: `WITH bal AS (
  SELECT p.id, p.name, coalesce(p.mobile, '') AS mobile,
         p.opening_balance + coalesce((SELECT sum(l.debit - l.credit) FROM party_ledger l WHERE l.party_id = p.id AND l.entry_date <= @to), 0) AS balance
  FROM party p WHERE p.kind IN ('customer', 'both') AND (@party::bigint IS NULL OR p.id = @party)
), age AS (
  SELECT b.party_id,
         sum(b.balance_due) FILTER (WHERE @to::date - b.bill_date <= 30) AS d0_30,
         sum(b.balance_due) FILTER (WHERE @to::date - b.bill_date BETWEEN 31 AND 60) AS d31_60,
         sum(b.balance_due) FILTER (WHERE @to::date - b.bill_date BETWEEN 61 AND 90) AS d61_90,
         sum(b.balance_due) FILTER (WHERE @to::date - b.bill_date > 90) AS d90_plus,
         sum(b.balance_due) AS total
  FROM bill b WHERE b.status = 'active' AND b.posts_to_ledger AND b.balance_due > 0 AND b.bill_date <= @to
  GROUP BY b.party_id)
SELECT bal.name AS party, bal.mobile, bal.balance, coalesce(age.d0_30, 0) AS d0_30, coalesce(age.d31_60, 0) AS d31_60,
       coalesce(age.d61_90, 0) AS d61_90, coalesce(age.d90_plus, 0) AS d90_plus, bal.balance - coalesce(age.total, 0) AS other
FROM bal LEFT JOIN age ON age.party_id = bal.id
WHERE bal.balance > 0 ORDER BY bal.balance DESC`,
	},
	"payables-ageing": {
		Title: "Payables ageing",
		Columns: []api.ReportColumn{col("party", "Dealer", "text"), col("balance", "Payable", "money"), col("d0_30", "0-30 days", "money"),
			col("d31_60", "31-60 days", "money"), col("d61_90", "61-90 days", "money"), col("d90_plus", "90+ days", "money"),
			col("other", "Opening / advances", "money")},
		Sum: []string{"balance", "d0_30", "d31_60", "d61_90", "d90_plus", "other"},
		SQL: `WITH bal AS (
  SELECT p.id, p.name,
         -(p.opening_balance + coalesce((SELECT sum(l.debit - l.credit) FROM party_ledger l WHERE l.party_id = p.id AND l.entry_date <= @to), 0)) AS balance
  FROM party p WHERE p.kind IN ('supplier', 'both') AND (@party::bigint IS NULL OR p.id = @party)
), dues AS (
  SELECT pu.supplier_id, pu.received_date,
         pu.grand_total - coalesce((SELECT sum(a.amount) FROM payment_allocation a JOIN payment py ON py.id = a.payment_id
                                     WHERE a.ref_type = 'purchase' AND a.ref_id = pu.id AND py.status = 'active'
                                       AND coalesce(py.cheque_status, 'cleared') <> 'bounced'), 0) AS due
  FROM purchase pu WHERE pu.status = 'active' AND pu.received_date <= @to
), age AS (
  SELECT supplier_id,
         sum(due) FILTER (WHERE @to::date - received_date <= 30) AS d0_30,
         sum(due) FILTER (WHERE @to::date - received_date BETWEEN 31 AND 60) AS d31_60,
         sum(due) FILTER (WHERE @to::date - received_date BETWEEN 61 AND 90) AS d61_90,
         sum(due) FILTER (WHERE @to::date - received_date > 90) AS d90_plus,
         sum(due) AS total
  FROM dues WHERE due > 0 GROUP BY supplier_id)
SELECT bal.name AS party, bal.balance, coalesce(age.d0_30, 0) AS d0_30, coalesce(age.d31_60, 0) AS d31_60,
       coalesce(age.d61_90, 0) AS d61_90, coalesce(age.d90_plus, 0) AS d90_plus, bal.balance - coalesce(age.total, 0) AS other
FROM bal LEFT JOIN age ON age.supplier_id = bal.id
WHERE bal.balance > 0 ORDER BY bal.balance DESC`,
	},
	"collections": {
		Title: "Collections",
		Columns: []api.ReportColumn{col("pay_date", "Date", "date"), col("doc_no", "Receipt", "text"), col("party", "Received from", "text"),
			col("mode", "Mode", "text"), col("reference", "Reference", "text"), col("amount", "Amount", "money"),
			col("cheque_status", "Cheque", "text"), col("status", "Status", "text")},
		Sum: []string{"amount"},
		SQL: `SELECT p.pay_date, p.doc_no, coalesce(pt.name, b.cust_name, '') AS party, p.mode::text AS mode,
       coalesce(p.reference, p.cheque_no, '') AS reference, p.amount, coalesce(p.cheque_status::text, '') AS cheque_status,
       p.status::text AS status
FROM payment p LEFT JOIN party pt ON pt.id = p.party_id LEFT JOIN bill b ON b.id = p.bill_id
WHERE p.direction = 'received' AND p.pay_date BETWEEN @from AND @to AND (@party::bigint IS NULL OR p.party_id = @party)
ORDER BY p.pay_date, p.doc_no`,
	},
	"payments-made": {
		Title: "Payments made",
		Columns: []api.ReportColumn{col("pay_date", "Date", "date"), col("doc_no", "Voucher", "text"), col("party", "Paid to", "text"),
			col("mode", "Mode", "text"), col("reference", "Reference", "text"), col("amount", "Amount", "money"),
			col("cheque_status", "Cheque", "text"), col("status", "Status", "text")},
		Sum: []string{"amount"},
		SQL: `SELECT p.pay_date, p.doc_no, coalesce(pt.name, '') AS party, p.mode::text AS mode,
       coalesce(p.reference, p.cheque_no, '') AS reference, p.amount, coalesce(p.cheque_status::text, '') AS cheque_status,
       p.status::text AS status
FROM payment p LEFT JOIN party pt ON pt.id = p.party_id
WHERE p.direction = 'paid' AND p.pay_date BETWEEN @from AND @to AND (@party::bigint IS NULL OR p.party_id = @party)
ORDER BY p.pay_date, p.doc_no`,
	},
	"profit": {
		Title: "Profit by bill",
		Columns: []api.ReportColumn{col("bill_date", "Date", "date"), col("bill_no", "Bill no", "text"), col("customer", "Customer", "text"),
			col("sales", "Sales (items taxable)", "money"), col("cost", "Cost", "money"), col("profit", "Profit", "money"),
			col("margin_pct", "Margin %", "percent")},
		Sum: []string{"sales", "cost", "profit"},
		SQL: `SELECT b.bill_date, b.bill_no, b.cust_name AS customer, b.items_taxable AS sales, b.cost_total AS cost,
       b.items_taxable - b.cost_total AS profit,
       CASE WHEN b.items_taxable > 0 THEN round((b.items_taxable - b.cost_total) * 100 / b.items_taxable, 2) ELSE 0 END AS margin_pct
FROM bill b WHERE ` + salesBills + ` ORDER BY b.bill_date, b.bill_no`,
	},
	"edits-cancellations": {
		Title: "Edits and cancellations",
		Columns: []api.ReportColumn{col("date", "Date", "date"), col("bill_no", "Bill no", "text"), col("action", "Action", "text"),
			col("version", "Version", "qty"), col("reason", "Reason", "text"), col("user", "By", "text")},
		Sum: []string{},
		SQL: `SELECT * FROM (
  SELECT (r.edited_at AT TIME ZONE 'Asia/Kolkata')::date AS date, b.bill_no, 'edit' AS action, r.version::numeric AS version,
         r.reason, coalesce(u.full_name, '') AS "user", r.edited_at AS at
  FROM bill_revision r JOIN bill b ON b.id = r.bill_id LEFT JOIN app_user u ON u.id = r.edited_by
  UNION ALL
  SELECT (b.cancelled_at AT TIME ZONE 'Asia/Kolkata')::date, b.bill_no, 'cancel', b.version::numeric, coalesce(b.cancel_reason, ''),
         coalesce(u.full_name, ''), b.cancelled_at
  FROM bill b LEFT JOIN app_user u ON u.id = b.cancelled_by WHERE b.status = 'cancelled'
) x WHERE x.date BETWEEN @from AND @to ORDER BY x.at`,
	},
}
